import json
from pathlib import Path
p = Path('products/services/public-data-prize-trial/gems-overview-evidence.json')
obj = json.loads(p.read_text())
terms = ('deadline', 'eligible', 'eligibility', 'citizen', 'resident', 'canada', 'united states', 'submission', 'rules', 'phase', 'prize')
def strings(value):
    if isinstance(value, str):
        yield value
    elif isinstance(value, list):
        for item in value:
            yield from strings(item)
    elif isinstance(value, dict):
        for item in value.values():
            yield from strings(item)
rows = list(dict.fromkeys(s for s in strings(obj) if any(t in s.lower() for t in terms)))
print(json.dumps({'source': str(p), 'matching_strings': len(rows), 'navigation_excerpts': [s[:480] for s in rows[:16]]}, ensure_ascii=False))
